// Generated from app/library/prophet-passages.ts by npm run build. Do not edit.
export const PROPHET_PASSAGES = [
  { english: "Adam", indonesian: "Nabi Adam", arabic: "\u0622\u062F\u064E\u0645", surah: 7, verse: 11, reference: "Al-A\u2018raf 7:11\u201327", referenceId: "Al-A\u2018raf 7:11\u201327", storyEn: "The Quran describes Adam\u2019s creation, the angels\u2019 command to bow, and Iblis\u2019s refusal. Adam and his wife are tested in the garden, recognize their mistake, and turn back to God. The passage closes with their descent to earthly life and guidance for humankind.", storyId: "Al-Qur\u2019an mengisahkan penciptaan Adam, perintah kepada para malaikat untuk bersujud, dan penolakan Iblis. Adam dan istrinya diuji di taman, menyadari kekeliruan, lalu memohon ampun kepada Allah. Kisah ini berlanjut dengan turunnya mereka ke bumi dan petunjuk bagi manusia." },
  { english: "Idris", indonesian: "Nabi Idris", arabic: "\u0625\u0650\u062F\u0652\u0631\u0650\u064A\u0633", surah: 19, verse: 56, reference: "Maryam 19:56\u201357", referenceId: "Maryam 19:56\u201357", storyEn: "The Quran names Idris as truthful and a prophet, and says that God raised him to a high station. It does not provide a longer narrative of his life in these verses.", storyId: "Al-Qur\u2019an menyebut Idris sebagai seorang yang sangat benar dan seorang nabi, serta menyatakan bahwa Allah mengangkatnya ke martabat yang tinggi. Ayat-ayat ini tidak memuat kisah hidup Idris yang lebih panjang.", noteEn: "The Quran gives only a brief account here.", noteId: "Al-Qur\u2019an hanya memberi keterangan singkat di sini." },
  { english: "Nuh", indonesian: "Nabi Nuh", arabic: "\u0646\u064F\u0648\u062D", surah: 11, verse: 25, reference: "Hud 11:25\u201349", referenceId: "Hud 11:25\u201349", storyEn: "Nuh calls his people to worship God and warns them, but many reject him. God instructs him to build the Ark; the flood comes, and those who believe are saved. The passage also recounts Nuh\u2019s grief for his son and teaches him to entrust judgment to God.", storyId: "Nuh menyeru kaumnya untuk menyembah Allah dan memberi peringatan, tetapi banyak yang menolak. Allah memerintahkannya membuat bahtera; banjir datang dan orang-orang beriman diselamatkan. Bagian ini juga menceritakan kesedihan Nuh atas putranya serta mengajarkan agar ia menyerahkan keputusan kepada Allah." },
  { english: "Hud", indonesian: "Nabi Hud", arabic: "\u0647\u064F\u0648\u062F", surah: 11, verse: 50, reference: "Hud 11:50\u201360", referenceId: "Hud 11:50\u201360", storyEn: "Hud is sent to the people of \u02BF\u0100d. He urges them to worship God and seek forgiveness, while they boast of their strength and reject his warning. The Quran says Hud and the believers are saved, while a fierce wind overtakes those who persist in denial.", storyId: "Hud diutus kepada kaum \u2018Ad. Ia mengajak mereka menyembah Allah dan memohon ampun, sementara mereka membanggakan kekuatan dan menolak peringatannya. Al-Qur\u2019an menyebut Hud dan orang-orang beriman diselamatkan, sedangkan kaum yang terus ingkar ditimpa angin yang dahsyat." },
  { english: "Salih", indonesian: "Nabi Saleh", arabic: "\u0635\u064E\u0627\u0644\u0650\u062D", surah: 11, verse: 61, reference: "Hud 11:61\u201368", referenceId: "Hud 11:61\u201368", storyEn: "Salih is sent to Thamud and calls them to worship God. The she-camel is given as a sign, with a clear instruction not to harm her. The people defy the command, and the Quran describes the destruction that follows.", storyId: "Saleh diutus kepada kaum Tsamud dan mengajak mereka menyembah Allah. Unta betina diberikan sebagai tanda, disertai larangan untuk mengganggunya. Kaumnya melanggar perintah itu, lalu Al-Qur\u2019an menggambarkan kehancuran yang menimpa mereka." },
  { english: "Ibrahim", indonesian: "Nabi Ibrahim", arabic: "\u0625\u0650\u0628\u0652\u0631\u064E\u0627\u0647\u0650\u064A\u0645", surah: 21, verse: 51, reference: "Al-Anbiya 21:51\u201373", referenceId: "Al-Anbiya 21:51\u201373", storyEn: "Ibrahim questions the worship of idols and calls his people to recognize the one God. When they try to punish him, God makes the fire safe for him. The Quran also describes God\u2019s gifts of family and prophethood, and Ibrahim\u2019s role in calling people toward worship and goodness.", storyId: "Ibrahim mempertanyakan penyembahan berhala dan mengajak kaumnya mengenal Tuhan Yang Esa. Ketika kaumnya berusaha menghukumnya, Allah menjadikan api itu tidak mencelakainya. Al-Qur\u2019an juga menyebut karunia keluarga dan kenabian serta peran Ibrahim dalam mengajak manusia beribadah dan berbuat baik." },
  { english: "Lut", indonesian: "Nabi Lut", arabic: "\u0644\u064F\u0648\u0637", surah: 11, verse: 77, reference: "Hud 11:77\u201383", referenceId: "Hud 11:77\u201383", storyEn: "Lut receives God\u2019s messengers as guests and is distressed by his people\u2019s harmful conduct. The messengers tell him to leave with his family during the night, except for his wife. The passage describes the town\u2019s destruction as a consequence of persistent wrongdoing.", storyId: "Lut menerima para utusan Allah sebagai tamu dan merasa gelisah melihat perbuatan kaumnya. Para utusan memintanya pergi pada malam hari bersama keluarganya, kecuali istrinya. Bagian ini menggambarkan kehancuran kota sebagai akibat dari kezaliman yang terus dilakukan." },
  { english: "Ismail", indonesian: "Nabi Ismail", arabic: "\u0625\u0650\u0633\u0652\u0645\u064E\u0627\u0639\u0650\u064A\u0644", surah: 2, verse: 125, reference: "Al-Baqarah 2:125\u2013129", referenceId: "Al-Baqarah 2:125\u2013129", storyEn: "The Quran praises Ismail as true to his promise and a messenger and prophet. It recounts Ibrahim and Ismail raising the foundations of the Kaaba and praying that their work be accepted and that a messenger be sent among their descendants. Another passage tells of Ibrahim and his son submitting during a test, but does not name the son in that passage.", storyId: "Al-Qur\u2019an memuji Ismail sebagai orang yang menepati janji serta seorang rasul dan nabi. Kisah lain menceritakan Ibrahim dan Ismail meninggikan fondasi Ka\u2018bah, berdoa agar amal mereka diterima, dan memohon agar seorang rasul diutus di antara keturunan mereka. Bagian lain mengisahkan Ibrahim dan putranya berserah diri saat diuji, tetapi ayat itu tidak menyebut nama sang putra.", noteEn: "The Quran does not name the son in the sacrifice account; later Islamic tradition commonly identifies him as Ismail.", noteId: "Al-Qur\u2019an tidak menyebut nama putra dalam kisah pengorbanan; tradisi Islam kemudian umumnya mengidentifikasikannya sebagai Ismail." },
  { english: "Ishaq", indonesian: "Nabi Ishaq", arabic: "\u0625\u0650\u0633\u0652\u062D\u064E\u0627\u0642", surah: 11, verse: 69, reference: "Hud 11:69\u201376", referenceId: "Hud 11:69\u201376", storyEn: "Messengers visit Ibrahim and give him and Sarah the news of Ishaq\u2019s birth, followed by Yaqub. The Quran names Ishaq among the righteous and blessed prophets. It does not give an extended independent biography in this passage.", storyId: "Para utusan datang kepada Ibrahim dan menyampaikan kabar gembira kepada Ibrahim dan Sarah tentang kelahiran Ishaq, lalu Yaqub. Al-Qur\u2019an menyebut Ishaq sebagai nabi yang saleh dan diberkahi. Bagian ini tidak memuat biografi panjang yang berdiri sendiri.", noteEn: "This account focuses on the announcement of his birth and blessing.", noteId: "Bagian ini berfokus pada kabar kelahiran dan keberkahannya." },
  { english: "Yaqub", indonesian: "Nabi Yaqub", arabic: "\u064A\u064E\u0639\u0652\u0642\u064F\u0648\u0628", surah: 12, verse: 4, reference: "Yusuf 12:4\u20136, 12:84\u201387", referenceId: "Yusuf 12:4\u20136 \xB7 12:84\u201387", storyEn: "Yaqub recognizes the meaning of Yusuf\u2019s dream and advises him with care. Years later, he grieves deeply when Yusuf is lost, yet says that he turns his sorrow to God and keeps hope. The Quran presents his patience and trust through the family\u2019s long separation and reunion.", storyId: "Yaqub memahami arti mimpi Yusuf dan menasihatinya dengan penuh perhatian. Bertahun-tahun kemudian ia berduka saat Yusuf hilang, tetapi menyerahkan kesedihannya kepada Allah dan tetap berharap. Al-Qur\u2019an menggambarkan kesabaran dan kepercayaannya sepanjang perpisahan panjang hingga keluarganya kembali berkumpul." },
  { english: "Yusuf", indonesian: "Nabi Yusuf", arabic: "\u064A\u064F\u0648\u0633\u064F\u0641", surah: 12, verse: 4, reference: "Yusuf 12:4\u2013101", referenceId: "Yusuf 12:4\u2013101", storyEn: "Yusuf\u2019s dream leads to jealousy among his brothers, and he is taken far from home. In Egypt he faces injustice, prison, and a chance to interpret the ruler\u2019s dream. His insight helps prepare for famine; years later he reunites with his family and chooses forgiveness.", storyId: "Mimpi Yusuf memicu kecemburuan saudara-saudaranya, lalu ia terpisah jauh dari rumah. Di Mesir ia menghadapi ketidakadilan, penjara, dan kesempatan menafsirkan mimpi penguasa. Pengetahuannya membantu masyarakat bersiap menghadapi masa sulit; bertahun-tahun kemudian ia bertemu kembali dengan keluarganya dan memilih memaafkan." },
  { english: "Ayyub", indonesian: "Nabi Ayyub", arabic: "\u0623\u064E\u064A\u064F\u0651\u0648\u0628", surah: 38, verse: 41, reference: "Sad 38:41\u201344", referenceId: "Sad 38:41\u201344", storyEn: "Ayyub calls to God while enduring hardship. God answers his prayer, brings relief, and restores his household as a mercy. The passage remembers Ayyub as patient and devoted without treating later folklore as Quranic detail.", storyId: "Ayyub berdoa kepada Allah saat menghadapi kesulitan. Allah menjawab doanya, memberinya jalan keluar, dan memulihkan keluarganya sebagai rahmat. Bagian ini mengenang Ayyub sebagai hamba yang sabar dan taat tanpa menambahkan cerita rakyat sebagai detail Al-Qur\u2019an." },
  { english: "Shuayb", indonesian: "Nabi Syuaib", arabic: "\u0634\u064F\u0639\u064E\u064A\u0652\u0628", surah: 11, verse: 84, reference: "Hud 11:84\u201395", referenceId: "Hud 11:84\u201395", storyEn: "Shuayb is sent to Midian and calls people to worship God, use fair measures, and stop cheating others. His people reject him and mock his warning. The Quran describes the rescue of Shuayb and the believers, and the fate of those who persisted in injustice.", storyId: "Syuaib diutus kepada Madyan dan mengajak kaumnya menyembah Allah, menggunakan takaran yang adil, dan berhenti merugikan orang lain. Kaumnya menolak dan mengejek peringatannya. Al-Qur\u2019an menggambarkan keselamatan Syuaib dan orang-orang beriman serta akhir kaum yang terus berbuat zalim." },
  { english: "Musa", indonesian: "Nabi Musa", arabic: "\u0645\u064F\u0648\u0633\u064E\u0649\u0670", surah: 20, verse: 9, reference: "Taha 20:9\u201398", referenceId: "Taha 20:9\u201398", storyEn: "At the sacred valley, Musa receives his call and signs, including the staff and the shining hand. He asks for Harun to help him speak and confronts Pharaoh. After the Israelites are delivered, Musa leaves them in Harun\u2019s care; the passage also tells how a calf becomes an object of worship while he is away.", storyId: "Di lembah suci, Musa menerima panggilan dan tanda-tanda, termasuk tongkat dan tangan yang bercahaya. Ia meminta Harun membantunya berbicara, lalu menghadapi Fir\u2018aun. Setelah Bani Israil diselamatkan, Musa menitipkan mereka kepada Harun; bagian ini juga menceritakan penyembahan anak sapi saat Musa pergi." },
  { english: "Harun", indonesian: "Nabi Harun", arabic: "\u0647\u064E\u0627\u0631\u064F\u0648\u0646", surah: 20, verse: 29, reference: "Taha 20:29\u201336", referenceId: "Taha 20:29\u201336", storyEn: "Musa asks God to appoint Harun, his brother, as a helper and partner in the mission. Harun shares the call to Pharaoh and later urges the Israelites not to follow the calf worship. The Quran recounts the brothers\u2019 disagreement after Musa returns, while preserving Harun\u2019s explanation that he tried to keep the community together.", storyId: "Musa memohon agar Harun, saudaranya, dijadikan penolong dan rekan dalam tugas kenabian. Harun ikut menyeru Fir\u2018aun dan kemudian mengingatkan Bani Israil agar tidak mengikuti penyembahan anak sapi. Al-Qur\u2019an menceritakan perbedaan mereka setelah Musa kembali, sekaligus menjelaskan upaya Harun menjaga kaumnya tetap bersatu." },
  { english: "Dhu al-Kifl", indonesian: "Nabi Zulkifli", arabic: "\u0630\u064F\u0648 \u0627\u0644\u0652\u0643\u0650\u0641\u0652\u0644", surah: 21, verse: 85, reference: "Al-Anbiya 21:85\u201386", referenceId: "Al-Anbiya 21:85\u201386", storyEn: "Dhu al-Kifl is named alongside Ismail and Idris among those who showed patience and were admitted to God\u2019s mercy. The Quran also places him among the best. These verses do not narrate a detailed biography or identify a historical timeline.", storyId: "Zulkifli disebut bersama Ismail dan Idris sebagai orang-orang yang sabar dan memperoleh rahmat Allah. Al-Qur\u2019an juga memasukkannya di antara orang-orang pilihan. Ayat-ayat ini tidak menceritakan biografi terperinci atau menetapkan kronologi sejarah.", noteEn: "The Quran gives only a short description; later identifications are not presented here as fact.", noteId: "Al-Qur\u2019an hanya memberi keterangan singkat; identifikasi dari sumber kemudian tidak disajikan sebagai fakta di sini." },
  { english: "Dawud", indonesian: "Nabi Daud", arabic: "\u062F\u064E\u0627\u0648\u064F\u06E5\u062F", surah: 38, verse: 17, reference: "Sad 38:17\u201326", referenceId: "Sad 38:17\u201326", storyEn: "Dawud is remembered for strength in worship and turning back to God. The Quran says he received wisdom and the Zabur, and describes his responsibility to judge with justice. It also mentions the mountains and birds joining him in glorifying God.", storyId: "Daud dikenang sebagai hamba yang kuat beribadah dan selalu kembali kepada Allah. Al-Qur\u2019an menyebut bahwa ia menerima hikmah dan Zabur serta mengemban tanggung jawab untuk memutuskan perkara dengan adil. Gunung-gunung dan burung-burung juga disebut bertasbih bersamanya." },
  { english: "Sulayman", indonesian: "Nabi Sulaiman", arabic: "\u0633\u064F\u0644\u064E\u064A\u0652\u0645\u064E\u0627\u0646", surah: 27, verse: 15, reference: "An-Naml 27:15\u201344", referenceId: "An-Naml 27:15\u201344", storyEn: "Sulayman inherits knowledge from Dawud and thanks God for it. The Quran tells of his ability to understand the ant, his encounter with the hoopoe, and his message to the Queen of Sheba. She visits, recognizes the truth, and submits to God; the account emphasizes gratitude and wisdom.", storyId: "Sulaiman mewarisi pengetahuan dari Daud dan bersyukur atas karunia itu. Al-Qur\u2019an menceritakan kemampuannya memahami semut, pertemuannya dengan burung hudhud, dan suratnya kepada Ratu Saba. Sang ratu datang, mengenali kebenaran, lalu berserah diri kepada Allah; kisah ini menonjolkan syukur dan kebijaksanaan." },
  { english: "Ilyas", indonesian: "Nabi Ilyas", arabic: "\u0625\u0650\u0644\u0652\u064A\u064E\u0627\u0633", surah: 37, verse: 123, reference: "As-Saffat 37:123\u2013132", referenceId: "As-Saffat 37:123\u2013132", storyEn: "Ilyas calls his people to worship God and leave their devotion to Baal. The Quran says that most of them reject him, while God praises Ilyas and grants peace to him among later generations.", storyId: "Ilyas menyeru kaumnya untuk menyembah Allah dan meninggalkan penyembahan Ba\u2018al. Al-Qur\u2019an menyebut kebanyakan mereka menolak, sementara Allah memuji Ilyas dan mengaruniakan salam kepadanya di kalangan generasi kemudian." },
  { english: "Al-Yasa", indonesian: "Nabi Ilyasa", arabic: "\u0627\u0644\u0652\u064A\u064E\u0633\u064E\u0639", surah: 6, verse: 86, reference: "Al-An\u2018am 6:86 \xB7 brief mention", referenceId: "Al-An\u2018am 6:86 \xB7 disebut singkat", storyEn: "Al-Yasa is listed among the prophets and the righteous. The Quran gives no extended narrative of his life in the cited verses, so this entry stays with that brief mention.", storyId: "Ilyasa disebut di antara para nabi dan orang-orang saleh. Ayat yang dirujuk tidak memuat kisah hidupnya secara panjang, sehingga bacaan ini terbatas pada penyebutan singkat tersebut.", noteEn: "The Quran gives only a brief mention here.", noteId: "Al-Qur\u2019an hanya menyebutnya secara singkat di sini." },
  { english: "Yunus", indonesian: "Nabi Yunus", arabic: "\u064A\u064F\u0648\u0646\u064F\u0633", surah: 37, verse: 139, reference: "As-Saffat 37:139\u2013148", referenceId: "As-Saffat 37:139\u2013148", storyEn: "Yunus leaves by ship, is cast into the sea, and calls to God from darkness. God answers him and brings him to safety. The Quran says he is sent to a community that believes, and that God grants them respite.", storyId: "Yunus pergi dengan kapal, dilemparkan ke laut, lalu berdoa kepada Allah dari dalam kegelapan. Allah menjawab doanya dan menyelamatkannya. Al-Qur\u2019an menyebut ia diutus kepada suatu kaum yang kemudian beriman, sehingga mereka diberi kesempatan hidup." },
  { english: "Zakariya", indonesian: "Nabi Zakaria", arabic: "\u0632\u064E\u0643\u064E\u0631\u0650\u064A\u064E\u0651\u0627", surah: 19, verse: 2, reference: "Maryam 19:2\u201311", referenceId: "Maryam 19:2\u201311", storyEn: "Zakariya cares for Mary and witnesses signs of God\u2019s provision. Though old and worried about who will carry on after him, he prays for a righteous child. God gives him the good news of Yahya and a sign that he will not speak to people for three nights while remaining well.", storyId: "Zakaria mengasuh Maryam dan menyaksikan tanda-tanda rezeki dari Allah. Meski telah lanjut usia dan khawatir tentang penerus setelahnya, ia berdoa agar dikaruniai anak yang saleh. Allah memberinya kabar tentang Yahya serta tanda bahwa ia tidak berbicara kepada manusia selama tiga malam dalam keadaan sehat." },
  { english: "Yahya", indonesian: "Nabi Yahya", arabic: "\u064A\u064E\u062D\u0652\u064A\u064E\u0649\u0670", surah: 19, verse: 12, reference: "Maryam 19:12\u201315", referenceId: "Maryam 19:12\u201315", storyEn: "Yahya is given wisdom while still young. The Quran describes him as compassionate, pure, dutiful to his parents, and not arrogant or rebellious. It sends peace upon him on the day he was born, the day he dies, and the day he is raised again.", storyId: "Yahya diberi hikmah sejak masih muda. Al-Qur\u2019an menggambarkannya sebagai pribadi yang penuh kasih, suci, berbakti kepada orang tua, serta tidak sombong dan tidak durhaka. Salam diberikan kepadanya pada hari kelahiran, wafat, dan kebangkitannya kembali." },
  { english: "Isa", indonesian: "Nabi Isa", arabic: "\u0639\u0650\u064A\u0633\u064E\u0649\u0670", surah: 19, verse: 16, reference: "Maryam 19:16\u201336", referenceId: "Maryam 19:16\u201336", storyEn: "Mary receives the news of a son through God\u2019s command and gives birth to Isa. As an infant, Isa speaks in the cradle, declaring himself a servant and prophet of God. The Quran recounts signs given to him by God\u2019s permission and his call to worship God alone.", storyId: "Maryam menerima kabar tentang seorang putra melalui ketetapan Allah dan melahirkan Isa. Saat masih bayi, Isa berbicara dari buaian dan menyatakan dirinya sebagai hamba serta nabi Allah. Al-Qur\u2019an menyebut tanda-tanda yang diberikan kepadanya dengan izin Allah dan seruannya untuk menyembah Allah semata." },
  { english: "Muhammad", indonesian: "Nabi Muhammad", arabic: "\u0645\u064F\u062D\u064E\u0645\u064E\u0651\u062F", surah: 33, verse: 21, reference: "Al-Ahzab 33:21, 33:40", referenceId: "Al-Ahzab 33:21 \xB7 33:40", storyEn: "The Quran presents Muhammad as God\u2019s messenger and the final prophet, and describes him as a beautiful example for those who hope in God. It calls him a mercy to all worlds. These selected verses provide a Quran-centered introduction, not a complete seerah or dated biography.", storyId: "Al-Qur\u2019an menyebut Muhammad sebagai utusan Allah dan nabi terakhir, serta teladan yang baik bagi orang yang berharap kepada Allah. Al-Qur\u2019an juga menggambarkannya sebagai rahmat bagi semesta alam. Ayat-ayat pilihan ini adalah pengantar berdasarkan Al-Qur\u2019an, bukan sirah lengkap atau biografi bertanggal." }
];
